<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Účetní portál · Byznio</title><style>body{margin:0;background:#f5f8fc;font-family:system-ui;color:#17233c}.wrap{max-width:1100px;margin:auto;padding:28px 18px}.card{background:#fff;border:1px solid #e1e7ef;border-radius:18px;padding:20px;margin:16px 0}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:10px;border-bottom:1px solid #edf1f6}.muted{color:#718096}</style></head><body><main class="wrap"><h1>Účetní portál</h1><p class="muted"><?=htmlspecialchars((string)$workspace,ENT_QUOTES,'UTF-8')?> · pouze pro čtení</p><div class="card"><h2>Vystavené doklady</h2><table class="table"><tr><th>Číslo</th><th>Typ</th><th>Datum</th><th>Splatnost</th><th>Částka</th><th>Stav</th></tr><?php foreach($documents as $d): ?><tr><td><?=htmlspecialchars($d['doc_number'])?></td><td><?=htmlspecialchars($d['doc_type'])?></td><td><?=htmlspecialchars($d['issue_date'])?></td><td><?=htmlspecialchars($d['due_date'])?></td><td><?=number_format((float)$d['total_with_vat'],2,',',' ')?> Kč</td><td><?=htmlspecialchars($d['payment_status'])?></td></tr><?php endforeach; ?></table></div><div class="card"><h2>Přijaté faktury</h2><table class="table"><tr><th>Dodavatel</th><th>Doklad</th><th>Datum</th><th>Splatnost</th><th>Částka</th><th>Stav</th></tr><?php foreach($received as $d): ?><tr><td><?=htmlspecialchars($d['supplier'])?></td><td><?=htmlspecialchars($d['document_number'])?></td><td><?=htmlspecialchars($d['issue_date'])?></td><td><?=htmlspecialchars($d['due_date'])?></td><td><?=number_format((float)$d['total_amount'],2,',',' ')?> Kč</td><td><?=htmlspecialchars($d['payment_status'])?></td></tr><?php endforeach; ?></table></div></main></body></html>
